INSERT INTO `phonemessage` VALUES (41927, 0, 99999993, 103, -1, '2025-01-06 00:25:55', 0, 'Это твоя первая подсказка! :sparkling_heart: Нажав на клавишу B можно завести транспорт.', 1, 1);
