  `character2` int NOT NULL,
  `character3` int NOT NULL,
  `characters` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '[-2,-2,-2,-2,-2,-2]',
  `present` tinyint NOT NULL DEFAULT 0,
  `refpresent` tinyint NOT NULL DEFAULT 0,
  `case` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '[0,0,0]',
  `RefferalId` int NOT NULL DEFAULT 0,
  `isSubscribe` tinyint(1) NOT NULL DEFAULT 0,
