  `ReceivedAwardWeek` int NOT NULL DEFAULT 0,
  `ReceivedAwardDonate` int NOT NULL DEFAULT 0,
  `Unique` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `LastSelectCharUUID` int NOT NULL DEFAULT 0,
  `ExitDate` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ga` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  PRIMARY KEY (`login`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin ROW_FORMAT = Dynamic;

